contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address owner, address spender) public payable {
        require(owner != address(0) || spender != address(0), "zero args");

        uint256 beforeOwnerBal = c.balanceOf(owner);
        uint256 beforeSpenderBal = c.balanceOf(spender);
        uint256 beforeSupply = c.totalSupply();

        uint256 first;
        bool revertedFirst;
        try c.allowance(owner, spender) returns (uint256 v) {
            first = v;
            revertedFirst = false;
        } catch {
            revertedFirst = true;
        }

        uint256 second;
        bool revertedSecond;
        try c.allowance(owner, spender) returns (uint256 v) {
            second = v;
            revertedSecond = false;
        } catch {
            revertedSecond = true;
        }

        uint256 beforeSupplyAgain = c.totalSupply();
        uint256 afterOwnerBal = c.balanceOf(owner);
        uint256 afterSpenderBal = c.balanceOf(spender);

        assert(
            revertedFirst == revertedSecond &&
            (!revertedFirst ? first == second : true) &&
            beforeOwnerBal == afterOwnerBal &&
            beforeSpenderBal == afterSpenderBal &&
            beforeSupply == beforeSupplyAgain
        );
    }
}

