contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public {
        // Set up so the deciding call has a chance to succeed.
        // Read before-values through c's public surface.
        uint256 senderBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(recipient);
        uint256 supplyBefore = c.totalSupply();

        // Precondition: enough balance for transfer to succeed.
        require(senderBefore >= amount, "!funds");

        // Deciding call: transfer must be its own top-level statement.
        bool reverted;
        try c.transfer(recipient, amount) returns (bool) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values.
        uint256 senderAfter = c.balanceOf(address(this));
        uint256 recipientAfter = c.balanceOf(recipient);
        uint256 supplyAfter = c.totalSupply();

        // General rule: on success, balances move by exactly amount and totalSupply is unchanged.
        assert(
            reverted
                || (senderAfter == senderBefore - amount
                    && recipientAfter == recipientBefore + amount
                    && supplyAfter == supplyBefore)
        );
    }

    receive() external payable {}
}

