        uint256 recipientBefore = c.balanceOf(recipient);
        bool ret;
        try c.transferAndCall(recipient, amount, data) {
            ret = true;
        } catch {
            ret = false;
        }
        uint256 senderAfter = c.balanceOf(sender);
        uint256 recipientAfter = c.balanceOf(recipient);
        assert(ret && senderAfter == senderBefore - amount && recipientAfter == recipientBefore + amount);
    }

    receive() external payable {}
}

