contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 synthBefore, uint256 poolCallerSeed) public {
        require(synthBefore > 0, "need positive balance");
        require(poolCallerSeed != 0, "need nonzero seed");

        address caller = address(uint160(uint256(keccak256(abi.encodePacked(poolCallerSeed)))) | 1);
        require(caller != address(0), "zero caller");

        // Pre-state observations through the public surface.
        uint256 debtBefore = c.getmapAddress_LPDebt(caller);

        // Drive c through its public burnSynth entry.
        bool reverted;
        try c.burnSynth() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 debtAfter = c.getmapAddress_LPDebt(caller);

        if (!reverted) {
            // The general rule: the call must not have increased the synthetic debt of the
            // pool caller, and any decrease must be driven by the synthetic balance that
            // existed before the call, never by the caller-provided seed/arguments.
            assert(debtAfter <= debtBefore);
            assert(debtBefore - debtAfter <= synthBefore);
        } else {
            // A reverted call must leave the observable debt untouched.
            assert(debtAfter == debtBefore);
        }
    }
}

