contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address member, uint amount) public {
        require(member != address(0), "member zero");
        // Force mintSynth(BASE, member) to be callable by making this contract a curated pool.
        // c.mintSynth requires onlyPool: msg.sender must be a curated pool.
        // We cannot guarantee that, so instead we call it and observe the revert behavior.
        // Read pre-state through public getters.
        uint debtBefore = c.getmapAddress_LPDebt(address(this));
        uint balBefore = c.balanceOf(member);
        uint supplyBefore = c.totalSupply();

        bool reverted;
        uint returned;
        try c.mintSynth(member, amount) returns (uint r) {
            returned = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // The minted synthetic amount equals the return value.
            assert(c.balanceOf(member) == balBefore + returned);
            // Total supply increases by the returned amount.
            assert(c.totalSupply() == supplyBefore + returned);
            // The caller's LP debt is incremented by the requested amount.
            assert(c.getmapAddress_LPDebt(address(this)) == debtBefore + amount);
            // The returned amount equals the requested amount.
            assert(returned == amount);
        } else {
            // On revert, no state changes are observable.
            assert(c.balanceOf(member) == balBefore);
            assert(c.totalSupply() == supplyBefore);
            assert(c.getmapAddress_LPDebt(address(this)) == debtBefore);
        }
    }

    receive() external payable {}
}

