contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account, uint256 removeAmount, uint256 addedValue, address recipient, uint256 transferAmount) public {
        // General rule: any completed state-changing ERC20-style call must be
        // immediately observable through the public getters with the exact
        // BEP20-required post-state.  A faulty implementation (e.g. one that
        // ignores max-approval handling or reverts on zero / arithmetic
        // overflow) breaks this.

        require(account != address(0), "!account");
        require(recipient != address(0), "!recipient");

        uint256 allowanceBefore = c.allowance(account, msg.sender);
        bool approveReverted;
        bool approveReturned;
        try c.approve(msg.sender, removeAmount) returns (bool ok) {
            approveReturned = ok;
            approveReverted = false;
        } catch {
            approveReverted = true;
        }

        uint256 allowanceAfterApprove = c.allowance(account, msg.sender);

        bool increaseReverted;
        uint256 allowanceBeforeIncrease = c.allowance(account, msg.sender);
        try c.increaseAllowance(msg.sender, addedValue) {
            increaseReverted = false;
        } catch {
            increaseReverted = true;
        }
        uint256 allowanceAfterIncrease = c.allowance(account, msg.sender);

        uint256 balanceBefore = c.balanceOf(address(this));
        bool transferReverted;
        bool transferReturned;
        try c.transfer(recipient, transferAmount) returns (bool ok) {
            transferReturned = ok;
            transferReverted = false;
        } catch {
            transferReverted = true;
        }
        uint256 balanceAfter = c.balanceOf(address(this));

        // Master assertion: every branch that completes without reverting must
        // produce exactly the balance/allowance post-state BEP20 mandates.
        assert(
            (approveReturned == true && approveReverted == false && allowanceAfterApprove == removeAmount)
            &&
            (increaseReverted == false && allowanceAfterIncrease == allowanceBeforeIncrease + addedValue)
            &&
            (transferReturned == true && transferReverted == false && balanceAfter == balanceBefore - transferAmount)
        );
    }

    receive() external payable {}
}

