contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 addedValue, uint256 amount) public {
        require(spender != address(0), "!spender");
        c.approve(spender, amount);
        uint256 beforeAllowance = c.allowance(address(this), spender);
        bool reverted;
        try c.increaseAllowance(spender, addedValue) { reverted = false; } catch { reverted = true; }
        uint256 afterAllowance = c.allowance(address(this), spender);
        assert(reverted || afterAllowance == beforeAllowance + addedValue);
    }
}

