contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 startAllowance, uint256 subtractedValue) public {
        require(spender != address(0), "spender zero");
        require(subtractedValue <= startAllowance, "insufficient allowance");
        require(startAllowance < type(uint256).max, "max allowance edge");

        c.approve(spender, startAllowance);
        uint256 beforeAllowance = c.allowance(address(this), spender);

        bool reverted;
        try c.decreaseAllowance(spender, subtractedValue) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterAllowance = c.allowance(address(this), spender);
        assert(!reverted && afterAllowance == beforeAllowance - subtractedValue);
    }
}

