contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address owner, address recipient, uint256 amount, uint256 approval) public payable {
        require(owner != address(0));
        require(recipient != address(0));
        require(owner != recipient);

        c.mintSynth(address(this), approval);

        c.transfer(owner, amount);

        c.approve(address(this), amount);

        uint256 ownerBefore = c.balanceOf(owner);
        uint256 recipientBefore = c.balanceOf(recipient);

        c.transferFrom(owner, recipient, amount);

        uint256 ownerAfter = c.balanceOf(owner);
        uint256 recipientAfter = c.balanceOf(recipient);

        assert(recipientAfter - recipientBefore == amount && ownerBefore - ownerAfter == amount);
    }

    receive() external payable {}
}

